import{_ as a,c as t,o as s,ag as i}from"./chunks/framework.Ci10AEOF.js";const u=JSON.parse('{"title":"Frequently Asked Questions","description":"Short answers to the questions that come up most often, with links to the pages that cover them properly","frontmatter":{"title":"Frequently Asked Questions","description":"Short answers to the questions that come up most often, with links to the pages that cover them properly"},"headers":[],"relativePath":"engine/frequently_asked_questions.md","filePath":"engine/frequently_asked_questions.md","lastUpdated":1793057853000}'),n={name:"engine/frequently_asked_questions.md"};function o(r,e,h,d,l,c){return s(),t("div",null,e[0]||(e[0]=[i('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-is-the-relationship-between-oie-and-mirth-connect" tabindex="-1">What is the relationship between OIE and Mirth Connect? <a class="header-anchor" href="#what-is-the-relationship-between-oie-and-mirth-connect" aria-label="Permalink to &quot;What is the relationship between OIE and Mirth Connect?&quot;">​</a></h3><p>OIE is an open-source fork of Mirth Connect, created after Mirth Connect moved to a proprietary model. It continues under the Mozilla Public License 2.0. See <a href="./migrating_from_mirth_connect.html">Migrating from Mirth Connect</a> to move an existing server.</p><h3 id="what-java-version-is-required" tabindex="-1">What Java version is required? <a class="header-anchor" href="#what-java-version-is-required" aria-label="Permalink to &quot;What Java version is required?&quot;">​</a></h3><p>Java 17 or later.</p><h3 id="what-databases-are-supported" tabindex="-1">What databases are supported? <a class="header-anchor" href="#what-databases-are-supported" aria-label="Permalink to &quot;What databases are supported?&quot;">​</a></h3><p>Apache Derby (embedded, the default), PostgreSQL, MySQL, Oracle, and SQL Server. See <a href="./database_support.html">Database Support</a>.</p><h3 id="is-oie-free-to-use" tabindex="-1">Is OIE free to use? <a class="header-anchor" href="#is-oie-free-to-use" aria-label="Permalink to &quot;Is OIE free to use?&quot;">​</a></h3><p>Yes, under MPL 2.0, which allows free use, modification, and distribution.</p><h2 id="installation-and-setup" tabindex="-1">Installation and setup <a class="header-anchor" href="#installation-and-setup" aria-label="Permalink to &quot;Installation and setup&quot;">​</a></h2><h3 id="what-are-the-default-login-credentials" tabindex="-1">What are the default login credentials? <a class="header-anchor" href="#what-are-the-default-login-credentials" aria-label="Permalink to &quot;What are the default login credentials?&quot;">​</a></h3><p>The user is <code>admin</code>. On a new database its password is generated at first start and written once to the console and to <code>logs/mirth.log</code>, unless <code>server.initialadminpassword</code> was set in <code>conf/mirth.properties</code> beforehand. A database upgraded from an earlier release keeps its existing passwords. Every user sets a new password at first login. See <a href="./accessing_the_administrator.html#initial-admin-password">Initial admin password</a>.</p><h3 id="what-are-the-default-ports" tabindex="-1">What are the default ports? <a class="header-anchor" href="#what-are-the-default-ports" aria-label="Permalink to &quot;What are the default ports?&quot;">​</a></h3><p><code>8080</code> for HTTP (status page and <code>webstart.jnlp</code>) and <code>8443</code> for HTTPS (REST API and Administrator connections). The <a href="./web_administrator.html">Web Administrator</a> is a separate application that reaches the engine through the REST API on <code>8443</code>.</p><h3 id="do-i-have-to-use-the-desktop-administrator" tabindex="-1">Do I have to use the desktop Administrator? <a class="header-anchor" href="#do-i-have-to-use-the-desktop-administrator" aria-label="Permalink to &quot;Do I have to use the desktop Administrator?&quot;">​</a></h3><p>No. The <a href="./web_administrator.html">Web Administrator</a> is a separate application that provides the same administration in a browser. Both clients work against the same engine at the same time, so there is no cutover. Scripted and headless administration goes through the <a href="./command_line_interface.html">CLI</a> or the <a href="./rest_api.html">REST API</a>.</p><h3 id="should-i-use-derby-in-production" tabindex="-1">Should I use Derby in production? <a class="header-anchor" href="#should-i-use-derby-in-production" aria-label="Permalink to &quot;Should I use Derby in production?&quot;">​</a></h3><p>No. Derby is for development and evaluation. Use PostgreSQL, MySQL, Oracle, or SQL Server in production. See <a href="./database_support.html">Database Support</a>.</p><h3 id="how-do-i-change-the-database-after-installation" tabindex="-1">How do I change the database after installation? <a class="header-anchor" href="#how-do-i-change-the-database-after-installation" aria-label="Permalink to &quot;How do I change the database after installation?&quot;">​</a></h3><p>Update <code>database</code>, <code>database.url</code>, <code>database.username</code>, and <code>database.password</code> in <code>conf/mirth.properties</code> and restart. See <a href="./server_configuration.html">Server Configuration</a>.</p><h3 id="how-do-i-reset-the-admin-password" tabindex="-1">How do I reset the admin password? <a class="header-anchor" href="#how-do-i-reset-the-admin-password" aria-label="Permalink to &quot;How do I reset the admin password?&quot;">​</a></h3><p>From the CLI: <code>user changepw admin &quot;a-new-password-here&quot;</code>. The new password must meet the <a href="./user_management.html#password-policy">password policy</a>.</p><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h2><h3 id="what-is-a-channel" tabindex="-1">What is a channel? <a class="header-anchor" href="#what-is-a-channel" aria-label="Permalink to &quot;What is a channel?&quot;">​</a></h3><p>The fundamental processing unit: how messages are received (source connector), how they are transformed, and where they are sent (destination connectors). See <a href="./channels.html">Channels</a>.</p><h3 id="how-many-destinations-can-a-channel-have" tabindex="-1">How many destinations can a channel have? <a class="header-anchor" href="#how-many-destinations-can-a-channel-have" aria-label="Permalink to &quot;How many destinations can a channel have?&quot;">​</a></h3><p>No hard limit. Destinations process in order by default and can be configured to run in parallel.</p><h3 id="what-is-the-difference-between-deploy-and-start" tabindex="-1">What is the difference between Deploy and Start? <a class="header-anchor" href="#what-is-the-difference-between-deploy-and-start" aria-label="Permalink to &quot;What is the difference between Deploy and Start?&quot;">​</a></h3><p>Deploying turns a saved channel definition into a running object: scripts are compiled, connectors created, tables reconciled. Whether the channel then runs is decided by its <strong>Initial State</strong>, so a deploy can leave it started, paused, or stopped. Start acts on an already-deployed channel. See <a href="./channel_state.html">Deploy, Start, and Channel State</a>.</p><h3 id="how-do-i-pass-data-between-channels" tabindex="-1">How do I pass data between channels? <a class="header-anchor" href="#how-do-i-pass-data-between-channels" aria-label="Permalink to &quot;How do I pass data between channels?&quot;">​</a></h3><p>Use the Channel Writer (destination) and Channel Reader (source) connectors, or <code>router</code> (a <code>VMRouter</code>) to route programmatically. The global map can share state, but it is not a message-passing mechanism.</p><h3 id="what-happens-when-a-destination-fails" tabindex="-1">What happens when a destination fails? <a class="header-anchor" href="#what-happens-when-a-destination-fails" aria-label="Permalink to &quot;What happens when a destination fails?&quot;">​</a></h3><p>It depends on the queue settings: marked ERROR immediately with no queue, placed in the queue for retry with queue-on-failure, or already queued with always-queue. See <a href="./queueing.html">Queueing</a>.</p><h3 id="what-is-the-difference-between-the-source-filter-and-destination-filter" tabindex="-1">What is the difference between the source filter and destination filter? <a class="header-anchor" href="#what-is-the-difference-between-the-source-filter-and-destination-filter" aria-label="Permalink to &quot;What is the difference between the source filter and destination filter?&quot;">​</a></h3><p>The source filter runs once and decides whether the message is processed at all. Destination filters run per destination and decide whether each one processes it.</p><h3 id="how-do-i-route-a-message-to-only-some-destinations" tabindex="-1">How do I route a message to only some destinations? <a class="header-anchor" href="#how-do-i-route-a-message-to-only-some-destinations" aria-label="Permalink to &quot;How do I route a message to only some destinations?&quot;">​</a></h3><p>Use destination filters, or remove destinations from the source filter or transformer with <code>destinationSet</code>. It exists on the source connector only:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Source filter or source transformer</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">destinationSet.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">remove</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Destination 2&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span></code></pre></div><p><code>remove</code> also takes a single name or metadata id, and <code>removeAllExcept</code> inverts the selection.</p><h2 id="transformers-and-scripts" tabindex="-1">Transformers and scripts <a class="header-anchor" href="#transformers-and-scripts" aria-label="Permalink to &quot;Transformers and scripts&quot;">​</a></h2><h3 id="what-is-the-difference-between-msg-and-tmp" tabindex="-1">What is the difference between <code>msg</code> and <code>tmp</code>? <a class="header-anchor" href="#what-is-the-difference-between-msg-and-tmp" aria-label="Permalink to &quot;What is the difference between `msg` and `tmp`?&quot;">​</a></h3><p><code>msg</code> is the parsed inbound message. <code>tmp</code> is the parsed outbound template, and it exists only when the transformer has an outbound template configured. When it exists, the transformer&#39;s output is taken from <code>tmp</code> rather than <code>msg</code>. Both are modifiable.</p><p>Because a connector&#39;s filter and transformer are compiled into one script sharing one scope, <code>tmp</code> is reachable from the filter too, and a change made there is still in place when the transformer runs.</p><h3 id="what-javascript-engine-does-oie-use" tabindex="-1">What JavaScript engine does OIE use? <a class="header-anchor" href="#what-javascript-engine-does-oie-use" aria-label="Permalink to &quot;What JavaScript engine does OIE use?&quot;">​</a></h3><p>Mozilla Rhino, configured for ES6 by default, set by <code>rhino.languageversion</code> in <code>mirth.properties</code>.</p><h3 id="can-i-use-java-classes-in-my-javascript" tabindex="-1">Can I use Java classes in my JavaScript? <a class="header-anchor" href="#can-i-use-java-classes-in-my-javascript" aria-label="Permalink to &quot;Can I use Java classes in my JavaScript?&quot;">​</a></h3><p>Yes. Rhino runs on the JVM:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> uuid </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> java.util.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">UUID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">randomUUID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h3 id="what-is-e4x" tabindex="-1">What is E4X? <a class="header-anchor" href="#what-is-e4x" aria-label="Permalink to &quot;What is E4X?&quot;">​</a></h3><p>ECMAScript for XML, the syntax used to read and modify message content when the data type is XML-based: HL7 v2.x, HL7 v3.x, XML, EDI/X12, NCPDP, Delimited Text, and DICOM. It is not universal. With the JSON data type <code>msg</code> and <code>tmp</code> are ordinary JavaScript objects, and with Raw they are Strings, so bracket paths do not apply. See <a href="./data_types_and_formats.html">Data Types and Formats</a>.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Transformer, HL7 v2.x inbound data type</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> msg[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID.5&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID.5.1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h3 id="how-do-i-add-a-segment-to-an-hl7-message" tabindex="-1">How do I add a segment to an HL7 message? <a class="header-anchor" href="#how-do-i-add-a-segment-to-an-hl7-message" aria-label="Permalink to &quot;How do I add a segment to an HL7 message?&quot;">​</a></h3><p>Use E4X to create and append segments in a JavaScript transformer step. See the <a href="./script_scope_and_user_api.html">Script Scope and User API</a>.</p><h3 id="how-do-i-delete-a-segment-from-an-hl7-message" tabindex="-1">How do I delete a segment from an HL7 message? <a class="header-anchor" href="#how-do-i-delete-a-segment-from-an-hl7-message" aria-label="Permalink to &quot;How do I delete a segment from an HL7 message?&quot;">​</a></h3><p>With the <code>delete</code> keyword:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Transformer with an HL7 v2.x outbound template, so tmp exists</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tmp[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ZZ1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><h2 id="data-types" tabindex="-1">Data types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data types&quot;">​</a></h2><h3 id="what-data-types-are-supported" tabindex="-1">What data types are supported? <a class="header-anchor" href="#what-data-types-are-supported" aria-label="Permalink to &quot;What data types are supported?&quot;">​</a></h3><p>HL7 v2.x, HL7 v3.x, DICOM, XML, JSON, EDI/X12, NCPDP, Delimited Text, and Raw. See <a href="./data_types_and_formats.html">Data Types and Formats</a>.</p><h3 id="can-i-convert-between-data-types-in-a-single-channel" tabindex="-1">Can I convert between data types in a single channel? <a class="header-anchor" href="#can-i-convert-between-data-types-in-a-single-channel" aria-label="Permalink to &quot;Can I convert between data types in a single channel?&quot;">​</a></h3><p>Yes. Set different inbound and outbound data types per connector. Converting HL7 to XML needs no code. The engine does not convert HL7 or XML to JSON for you: build the JSON in a transformer step.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><h3 id="how-do-i-improve-channel-throughput" tabindex="-1">How do I improve channel throughput? <a class="header-anchor" href="#how-do-i-improve-channel-throughput" aria-label="Permalink to &quot;How do I improve channel throughput?&quot;">​</a></h3><ul><li>Set Message Storage to the minimum level you need</li><li>Use attachment handlers for large content</li><li>Enable source queuing where an auto-generated ACK is acceptable</li><li>Enable destination queuing where you do not need a synchronous response</li><li>Raise Max Processing Threads where message order does not matter</li><li>Raise Queue Threads where the downstream system tolerates parallel connections</li><li>Uncheck Wait for previous destination unless ordering between destinations matters</li><li>Use custom metadata columns for fields you search often</li></ul><h3 id="what-message-storage-mode-should-i-use" tabindex="-1">What Message Storage mode should I use? <a class="header-anchor" href="#what-message-storage-mode-should-i-use" aria-label="Permalink to &quot;What Message Storage mode should I use?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Environment</th><th>Mode</th></tr></thead><tbody><tr><td>Development and testing</td><td>Development (stores everything)</td></tr><tr><td>Production, troubleshooting needed</td><td>Production (raw, encoded, sent, response and maps)</td></tr><tr><td>Production, high throughput</td><td>Raw or Metadata</td></tr><tr><td>Maximum performance</td><td>Disabled (no storage)</td></tr></tbody></table><p>Metadata and Disabled store no message content, so a message processed in either mode cannot be reprocessed. Raw keeps the raw content, which is enough to reprocess it. See <a href="./message_lifecycle.html#message-storage-modes">Message storage modes</a>.</p><h3 id="how-do-i-handle-large-messages" tabindex="-1">How do I handle large messages? <a class="header-anchor" href="#how-do-i-handle-large-messages" aria-label="Permalink to &quot;How do I handle large messages?&quot;">​</a></h3><p>Use an attachment handler to extract large content from the message body and store it separately.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><h3 id="how-do-i-replace-the-self-signed-tls-certificate" tabindex="-1">How do I replace the self-signed TLS certificate? <a class="header-anchor" href="#how-do-i-replace-the-self-signed-tls-certificate" aria-label="Permalink to &quot;How do I replace the self-signed TLS certificate?&quot;">​</a></h3><p>Import a CA-signed certificate into the keystore with Java&#39;s <code>keytool</code>, or use a certificate management extension if you have one installed.</p><h3 id="how-do-i-encrypt-the-database-password-in-mirth-properties" tabindex="-1">How do I encrypt the database password in <code>mirth.properties</code>? <a class="header-anchor" href="#how-do-i-encrypt-the-database-password-in-mirth-properties" aria-label="Permalink to &quot;How do I encrypt the database password in `mirth.properties`?&quot;">​</a></h3><p>Set <code>encryption.properties = 1</code> in <code>mirth.properties</code>. On the next start the server rewrites <code>database.password</code> as an <code>{enc}</code> value, encrypted with the key in its keystore. It is off by default. See <a href="./security_and_compliance.html">Security and Compliance</a>.</p><h3 id="is-oie-hipaa-compliant" tabindex="-1">Is OIE HIPAA compliant? <a class="header-anchor" href="#is-oie-hipaa-compliant" aria-label="Permalink to &quot;Is OIE HIPAA compliant?&quot;">​</a></h3><p>OIE provides technical controls that support HIPAA compliance (encryption, access control, audit logging). Compliance also requires organizational policies and procedures, and is a property of your deployment rather than of the software. See <a href="./security_and_compliance.html">Security and Compliance</a>.</p><h2 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h2><h3 id="how-do-i-back-up-my-oie-instance" tabindex="-1">How do I back up my OIE instance? <a class="header-anchor" href="#how-do-i-back-up-my-oie-instance" aria-label="Permalink to &quot;How do I back up my OIE instance?&quot;">​</a></h3><ol><li>Export the server configuration from the CLI: <code>exportcfg &quot;backup.xml&quot;</code></li><li>Back up the <code>appdata/</code> directory, which holds the keystore and the embedded database if you use Derby</li><li>Back up <code>conf/mirth.properties</code></li><li>Back up the external database separately if you use one</li></ol><p>Without the keystore, encrypted content in a restored database cannot be read.</p><h3 id="how-do-i-prevent-the-database-from-growing-too-large" tabindex="-1">How do I prevent the database from growing too large? <a class="header-anchor" href="#how-do-i-prevent-the-database-from-growing-too-large" aria-label="Permalink to &quot;How do I prevent the database from growing too large?&quot;">​</a></h3><p>Enable the Data Pruner and configure per-channel policies, pruning content sooner than metadata. See <a href="./data_pruning_and_maintenance.html">Data Pruning and Maintenance</a>.</p>',83)]))}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
